gafu(){return"\u0426\u0435\u043d\u0443 \u0441\u0431\u0438\u0432\u0430\u0442\u044c \u0443\u0436\u0435 \u043d\u0435\u043a\u0443\u0434\u0430"},
gafg(){return"\u0421\u043a\u0440\u043e\u043c\u043d\u043e"},
gafb(){return"\u041e\u0431\u043e\u0441\u043d\u043e\u0432\u0430\u043d\u043d\u043e"},
gaff(){return"\u041f\u043e \u043c\u0430\u043a\u0441\u0438\u043c\u0443\u043c\u0443"},
gaf4(){return"\u041f\u043e\u043f\u0440\u043e\u0441\u0438\u0442\u044c"},
gafc(){return"\u0421\u043a\u043e\u043b\u044c\u043a\u043e \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u0442\u044c?"},
gafd(){return"\u0427\u0435\u043c \u0431\u043e\u043b\u044c\u0448\u0435 \u043f\u0440\u043e\u0441\u0438\u0442\u0435 \u2014 \u0442\u0435\u043c \u043c\u0435\u043d\u044c\u0448\u0435 \u0448\u0430\u043d\u0441 \u0438 \u0442\u0435\u0440\u043f\u0435\u043d\u0438\u0435 \u043f\u0440\u043e\u0434\u0430\u0432\u0446\u0430"},
af6(a){return"\u0448\u0430\u043d\u0441 "+a+"%"},
gaf1(){return"\u042d\u0442\u043e \u0443\u0436\u0435 \u0432 \u0446\u0435\u043d\u0435, \u0441\u043a\u0438\u0434\u044b\u0432\u0430\u0442\u044c \u043d\u0435\u043a\u0443\u0434\u0430."},
afa(a){return"\u0421\u0442\u043e\u043b\u044c\u043a\u043e \u043d\u0435 \u0441\u043a\u0438\u043d\u0443. \u0414\u0430\u0432\u0430\u0439 \u0442\u0430\u043a: \u043c\u0438\u043d\u0443\u0441 "+a+" \u2014 \u0438 \u043f\u043e \u0440\u0443\u043a\u0430\u043c."},
