gafS(){return"\u041f\u043e\u0434\u043a\u0440\u0430\u0448\u0438\u0432\u0430\u043b \u043f\u043e \u043c\u0435\u043b\u043e\u0447\u0438. \u041d\u0443 \u0441\u043a\u0438\u043d\u0443 \u043d\u0435\u043c\u043d\u043e\u0433\u043e."},
