gafl(){return"\u042d\u0442\u043e \u043c\u0435\u043b\u043e\u0447\u044c, \u0437\u0430 \u044d\u0442\u043e \u043d\u0435 \u0441\u043a\u0438\u043d\u0443."},
gafm(){return"\u042f \u044d\u0442\u043e \u0443\u0436\u0435 \u0432 \u0446\u0435\u043d\u0443 \u0437\u0430\u043b\u043e\u0436\u0438\u043b."},
gafn(){return"\u0418\u0449\u0438 \u0434\u0443\u0440\u0430\u043a\u0430 \u2014 \u043d\u0430 \u0445\u043e\u0434\u0443 \u043d\u0435 \u0432\u043b\u0438\u044f\u0435\u0442."},
gafo(){return"\u041d\u0435, \u044d\u0442\u043e \u0432\u0441\u0451 \u0440\u0435\u0448\u0430\u0435\u043c\u043e. \u0426\u0435\u043d\u0430 \u0442\u0430 \u0436\u0435."},
gafr(){return"\u0412\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u043e \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e, \u0441\u043a\u0438\u0434\u043a\u0438 \u043d\u0435 \u0431\u0443\u0434\u0435\u0442."},
gafs(){return"\u041e\u043a\u0440\u0430\u0441 \u2014 \u044d\u0442\u043e \u043d\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u043e \u0434\u043b\u044f \u0442\u0430\u043a\u043e\u0433\u043e \u0433\u043e\u0434\u0430. \u0411\u0435\u0437 \u0441\u043a\u0438\u0434\u043a\u0438."},
gaft(){return"\u041f\u043e\u0434\u043a\u0440\u0430\u0441\u043a\u0430 \u043d\u0435 \u043f\u043e\u0432\u043e\u0434. \u041d\u0435\u0442."},
gafp(){return"\u042f \u043d\u0435 \u0437\u043d\u0430\u043b, \u0447\u0442\u043e \u043a\u0440\u0430\u0448\u0435\u043d\u043e, \u043c\u043d\u0435 \u0442\u0430\u043a \u043f\u0440\u043e\u0434\u0430\u043b\u0438. \u0426\u0435\u043d\u0430 \u0442\u0430 \u0436\u0435."},
gafj(){return"\u0412\u0441\u0435 \u043d\u0430\u043b\u0438\u0447\u043d\u044b\u043c\u0438 \u043f\u043b\u0430\u0442\u044f\u0442, \u044d\u0442\u043e \u043d\u0435 \u0430\u0440\u0433\u0443\u043c\u0435\u043d\u0442."},
gafk(){return"\u041c\u043d\u0435 \u0431\u0435\u0437 \u0440\u0430\u0437\u043d\u0438\u0446\u044b, \u043a\u0430\u043a \u043f\u043b\u0430\u0442\u0438\u0448\u044c."},
gaeV(){return"\u043f\u0440\u043e\u0434\u0430\u0432\u0435\u0446 \u043d\u0435 \u0437\u0430\u0445\u043e\u0442\u0435\u043b \u043e\u0442\u0434\u0430\u0432\u0430\u0442\u044c \u043c\u0430\u0448\u0438\u043d\u0443 \u0447\u0443\u0436\u043e\u043c\u0443 \u0447\u0435\u043b\u043e\u0432\u0435\u043a\u0443"},
gaeW(){return"\u0434\u043e\u0432\u0435\u0440\u0435\u043d\u043d\u044b\u0439 \u0437\u0430\u0441\u0442\u0440\u044f\u043b \u0432 \u043f\u0440\u043e\u0431\u043a\u0435 \u0438 \u043e\u043f\u043e\u0437\u0434\u0430\u043b \u2014 \u043f\u0440\u043e\u0434\u0430\u0432\u0435\u0446 \u0443\u0435\u0445\u0430\u043b"},
gaeX(){return"\u043f\u0440\u043e\u0434\u0430\u0432\u0435\u0446 \u043f\u043e\u0434\u043d\u044f\u043b \u0446\u0435\u043d\u0443 \u043d\u0430 \u043c\u0435\u0441\u0442\u0435, \u0434\u043e\u0432\u0435\u0440\u0435\u043d\u043d\u044b\u0439 \u043d\u0435 \u0441\u0442\u0430\u043b \u0441\u043e\u0433\u043b\u0430\u0448\u0430\u0442\u044c\u0441\u044f"},
gaeY(){return"\u043f\u043e\u043a\u0443\u043f\u0430\u0442\u0435\u043b\u044c \u043d\u0435 \u0437\u0430\u0445\u043e\u0442\u0435\u043b \u043e\u0444\u043e\u0440\u043c\u043b\u044f\u0442\u044c \u043c\u0430\u0448\u0438\u043d\u0443 \u0447\u0435\u0440\u0435\u0437 \u043f\u043e\u0441\u0440\u0435\u0434\u043d\u0438\u043a\u0430"},
gaeZ(){return"\u0434\u043e\u0432\u0435\u0440\u0435\u043d\u043d\u044b\u0439 \u043e\u043f\u043e\u0437\u0434\u0430\u043b \u2014 \u043f\u043e\u043a\u0443\u043f\u0430\u0442\u0435\u043b\u044c \u043f\u0435\u0440\u0435\u0434\u0443\u043c\u0430\u043b"},
gaf_(){return"\u043f\u043e\u043a\u0443\u043f\u0430\u0442\u0435\u043b\u044c \u043d\u0430\u0447\u0430\u043b \u0441\u0431\u0438\u0432\u0430\u0442\u044c \u0446\u0435\u043d\u0443, \u0434\u043e\u0432\u0435\u0440\u0435\u043d\u043d\u044b\u0439 \u043d\u0435 \u0441\u043e\u0433\u043b\u0430\u0441\u0438\u043b\u0441\u044f"},
gAX(){return"\u041f\u043e\u043f\u0440\u043e\u0441\u0438\u0442\u044c \u0437\u0430\u0434\u0430\u0442\u043e\u043a?"},
AV(a){return"\u041f\u043e\u043a\u0443\u043f\u0430\u0442\u0435\u043b\u044c \u043f\u0435\u0440\u0435\u0432\u0435\u0434\u0451\u0442 "+a+", \u0438 \u043d\u0430 \u0432\u0441\u0442\u0440\u0435\u0447\u0435 \u0434\u043e\u043f\u043b\u0430\u0442\u0438\u0442 \u043e\u0441\u0442\u0430\u0442\u043e\u043a.\n\n\u0412\u0437\u044f\u043b\u0438 \u0437\u0430\u0434\u0430\u0442\u043e\u043a \u2014 \u043f\u0440\u043e\u0434\u0430\u0432\u0430\u0439\u0442\u0435 \u0438\u043c\u0435\u043d\u043d\u043e \u0435\u043c\u0443. \u041d\u0435 \u043f\u0440\u0438\u0435\u0434\u0435\u0442\u0435, \u043f\u0440\u043e\u0434\u0430\u0434\u0438\u0442\u0435 \u0434\u0440\u0443\u0433\u043e\u043c\u0443 \u0438\u043b\u0438 \u0441\u043d\u0438\u043c\u0435\u0442\u0435 \u043e\u0431\u044a\u044f\u0432\u043b\u0435\u043d\u0438\u0435, \u043d\u0435 \u0432\u0435\u0440\u043d\u0443\u0432 \u0434\u0435\u043d\u044c\u0433\u0438, \u2014 \u0431\u0430\u043d\u043a \u0437\u0430\u0431\u043b\u043e\u043a\u0438\u0440\u0443\u0435\u0442 \u043a\u0430\u0440\u0442\u0443 \u043f\u043e 161-\u0424\u0417, \u0440\u0435\u043f\u0443\u0442\u0430\u0446\u0438\u044f \u0443\u043f\u0430\u0434\u0451\u0442 \u043d\u0430 3,5 \u0437\u0432\u0435\u0437\u0434\u044b, \u043f\u043e\u043a\u0443\u043f\u0430\u0442\u044c \u043c\u0430\u0448\u0438\u043d\u044b \u0431\u0443\u0434\u0435\u0442 \u043d\u0435\u043b\u044c\u0437\u044f."},
gpB(){return"\u041e\u0442\u043c\u0435\u043d\u0430"},
gAU(){return"\u041f\u043e\u043f\u0440\u043e\u0441\u0438\u0442\u044c"},
B1(a){return"\ud83d\udcb8 \u0417\u0430\u0434\u0430\u0442\u043e\u043a "+a+" \u043f\u0440\u0438\u0448\u0451\u043b \u043d\u0430 \u043a\u0430\u0440\u0442\u0443"},
gB7(){return"\u041f\u043e\u043a\u0443\u043f\u0430\u0442\u0435\u043b\u044c \u043e\u0442\u043a\u0430\u0437\u0430\u043b\u0441\u044f \u0432\u043d\u043e\u0441\u0438\u0442\u044c \u0437\u0430\u0434\u0430\u0442\u043e\u043a"},
gAT(){return"\u0417\u0430\u0434\u0430\u0442\u043e\u043a \u043f\u043e \u044d\u0442\u043e\u0439 \u043c\u0430\u0448\u0438\u043d\u0435 \u0443\u0436\u0435 \u0432\u0437\u044f\u0442"},
gAS(){return"\u0412\u044b \u0443\u0436\u0435 \u043f\u0440\u043e\u0441\u0438\u043b\u0438 \u0437\u0430\u0434\u0430\u0442\u043e\u043a \u0443 \u044d\u0442\u043e\u0433\u043e \u043f\u043e\u043a\u0443\u043f\u0430\u0442\u0435\u043b\u044f"},
gB_(){return"\u0421\u043d\u0430\u0447\u0430\u043b\u0430 \u0434\u043e\u0433\u043e\u0432\u043e\u0440\u0438\u0442\u0435\u0441\u044c \u043e \u0446\u0435\u043d\u0435"},
gB5(){return"\u0412\u0435\u0440\u043d\u0443\u0442\u044c \u0437\u0430\u0434\u0430\u0442\u043e\u043a?"},
B3(a,b){return a+" \u043f\u043e\u043b\u0443\u0447\u0438\u0442 \u043e\u0431\u0440\u0430\u0442\u043d\u043e "+b+". \u0421\u0434\u0435\u043b\u043a\u0430 \u0441 \u043d\u0438\u043c \u043e\u0442\u043c\u0435\u043d\u0438\u0442\u0441\u044f, \u043d\u043e \u0431\u0435\u0437 \u0448\u0442\u0440\u0430\u0444\u0430."},
gpC(){return"\u0412\u0435\u0440\u043d\u0443\u0442\u044c"},
gB6(){return"\u0417\u0430\u0434\u0430\u0442\u043e\u043a \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0451\u043d"},
