ga7_(){return"\u041d\u0435\u0442. \u0412 \u043f\u0440\u043e\u0448\u043b\u044b\u0439 \u0440\u0430\u0437 \u0435\u043b\u0435 \u0434\u043e\u0436\u0434\u0430\u043b\u0438\u0441\u044c \u0441\u0432\u043e\u0438 \u0434\u0435\u043d\u044c\u0433\u0438."},
