Ap(a){return"\u0421\u0440\u043e\u043a \u0432\u044b\u0448\u0435\u043b "+a+" \u2014 \u0448\u0442\u0440\u0430\u0444 \u0432\u044b\u043f\u0438\u0441\u0430\u043d"},
Al(a,b){return"\u041f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c \u043d\u0430 \u0443\u0447\u0451\u0442 \u0434\u043e "+a+" (\u043e\u0441\u0442\u0430\u043b\u043e\u0441\u044c "+b+")"},
A5(a){var s=""+a,r=s+" \u0434\u043d\u044f"
return A.Y(a,r,this.a,s+" \u0434\u043d\u0435\u0439",s+" \u0434\u0435\u043d\u044c",r,null,null)},
