gpv(){return"\u041c\u0430\u0448\u0438\u043d\u0430 \u0443\u0436\u0435 \u043d\u0430 \u0443\u0447\u0451\u0442\u0435"},
gpy(){return"\ud83d\udccd \u041e\u0441\u043c\u043e\u0442\u0440 \u2014 \u0432 \u0413\u0418\u0411\u0414\u0414 \u0433\u043e\u0440\u043e\u0434\u0430, \u0433\u0434\u0435 \u0441\u0442\u043e\u0438\u0442 \u043c\u0430\u0448\u0438\u043d\u0430"},
