gafc(){return"\u0421\u043a\u0456\u043b\u044c\u043a\u0438 \u043f\u0440\u043e\u0441\u0438\u0442\u0438?"},
gafd(){return"\u0427\u0438\u043c \u0431\u0456\u043b\u044c\u0448\u0435 \u043f\u0440\u043e\u0441\u0438\u0442\u0435, \u0442\u0438\u043c \u043c\u0435\u043d\u0448\u0438\u0439 \u0448\u0430\u043d\u0441 \u0456 \u0442\u0435\u0440\u043f\u0456\u043d\u043d\u044f \u043f\u0440\u043e\u0434\u0430\u0432\u0446\u044f"},
af6(a){return"\u0448\u0430\u043d\u0441 "+a+"%"},
