gAX(){return"\u041f\u043e\u043f\u0440\u043e\u0441\u0438\u0442\u0438 \u0437\u0430\u0434\u0430\u0442\u043e\u043a?"},
AV(a){return"\u041f\u043e\u043a\u0443\u043f\u0435\u0446\u044c \u043f\u0435\u0440\u0435\u0432\u0435\u0434\u0435 "+a+", \u0430 \u0440\u0435\u0448\u0442\u0443 \u0437\u0430\u043f\u043b\u0430\u0442\u0438\u0442\u044c \u043d\u0430 \u0437\u0443\u0441\u0442\u0440\u0456\u0447\u0456.\n\n\u042f\u043a\u0449\u043e \u0432\u0456\u0437\u044c\u043c\u0435\u0442\u0435 \u0437\u0430\u0434\u0430\u0442\u043e\u043a, \u043f\u0440\u043e\u0434\u0430\u0439\u0442\u0435 \u0441\u0430\u043c\u0435 \u0446\u044c\u043e\u043c\u0443 \u043f\u043e\u043a\u0443\u043f\u0446\u044e. \u042f\u043a\u0449\u043e \u0437\u0443\u0441\u0442\u0440\u0456\u0447 \u0437\u0456\u0440\u0432\u0435\u0442\u044c\u0441\u044f \u0430\u0431\u043e \u0432\u0438 \u043f\u0440\u043e\u0434\u0430\u0441\u0442\u0435 \u0456\u043d\u0448\u043e\u043c\u0443 \u0447\u0438 \u043f\u0440\u0438\u0431\u0435\u0440\u0435\u0442\u0435 \u043e\u0433\u043e\u043b\u043e\u0448\u0435\u043d\u043d\u044f \u0431\u0435\u0437 \u043f\u043e\u0432\u0435\u0440\u043d\u0435\u043d\u043d\u044f \u0433\u0440\u043e\u0448\u0435\u0439, \u0431\u0430\u043d\u043a \u0437\u0430\u0431\u043b\u043e\u043a\u0443\u0454 \u0432\u0430\u0448\u0443 \u043a\u0430\u0440\u0442\u043a\u0443 (\u0424\u0417 \u2116 161), \u0440\u0435\u043f\u0443\u0442\u0430\u0446\u0456\u044f \u0432\u043f\u0430\u0434\u0435 \u043d\u0430 3.5 \u0437\u0456\u0440\u043a\u0438 \u0456 \u043a\u0443\u043f\u0443\u0432\u0430\u0442\u0438 \u043c\u0430\u0448\u0438\u043d\u0438 \u043d\u0435 \u0437\u043c\u043e\u0436\u0435\u0442\u0435."},
gpB(){return"\u0421\u043a\u0430\u0441\u0443\u0432\u0430\u0442\u0438"},
gAU(){return"\u041f\u043e\u043f\u0440\u043e\u0441\u0438\u0442\u0438"},
