gV9(){return"\ud83e\udddf \u041c\u0423\u041c\u0406\u042f \u041f\u0420\u041e\u041a\u0418\u0414\u0410\u0404\u0422\u042c\u0421\u042f! \u0411\u0435\u0437\u043a\u043e\u0448\u0442\u043e\u0432\u043d\u0456 \u043f\u0435\u0440\u0435\u043a\u0440\u0443\u0442\u0438, \u0434\u043e\u043a\u0438 \u0432\u043e\u043d\u0430 \u043d\u0435 \u043f\u0456\u0434\u0435"},
